contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint value, address target) public payable {
        require(address(this).balance >= value, "insufficient balance for value");
        require(target != address(0), "target is zero address");

        uint beforeC = address(c).balance;
        uint beforeTarget = target.balance;

        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(address(c).balance == beforeC - value);
            assert(target.balance == beforeTarget);
        } else {
            assert(address(c).balance == beforeC);
            assert(target.balance == beforeTarget);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value) public payable {
        require(target != address(0), "target is zero address");
        require(address(this).balance >= value, "insufficient balance");

        c.fallback{value: address(this).balance}();

        uint beforeC = address(c).balance;
        uint beforeTarget = target.balance;

        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            target.balance == beforeTarget &&
            (
                (reverted && address(c).balance == beforeC) ||
                (!reverted && address(c).balance == beforeC - value)
            )
        );
    }

    receive() external payable {}
}

